//! 🧵️ Immutable command frame is issued from one real parent Store read and its admitted child root.
use super::*;
use semio_framework_value::{NativeDecodeControl,ValueError,ValueRefusalKind};
pub(crate) struct ArtifactOwnedToolDocument<A:ArtifactApp>{
 parent:Option<store::SnapshotRead<A::Snapshot>>,
 snapshot_owner:Option<std::sync::Arc<A::Snapshot>>,
 children:Option<ChildContentView>,
 generation:u64,revision:[u8;32],child_generation:u64,
}
fn frame_fault(error:ValueError)->Fault{
 Fault::new(FaultOrigin::Framework,FaultCode::new("interactive-job.child-frame-refusal"),error.message).with_param("refusalKind",error.kind.as_str())
}
fn projection_fault(error:store::ChildRestoreProjectionError)->Fault{
 let kind=match error{
  store::ChildRestoreProjectionError::ReferenceLimit|store::ChildRestoreProjectionError::TraversalLimit=>ValueRefusalKind::WorkLimit,
  store::ChildRestoreProjectionError::InvalidSlot|store::ChildRestoreProjectionError::InvalidReference|store::ChildRestoreProjectionError::DuplicateChild|store::ChildRestoreProjectionError::SingularSlot|store::ChildRestoreProjectionError::IncompleteSet=>ValueRefusalKind::InvalidValue,
 };
 frame_fault(ValueError::new(kind,error.to_string()))
}
impl<A:ArtifactApp> ArtifactOwnedToolDocument<A>{
 pub(crate) fn capture<M:SpaceMember+MemberFactory+'static>(
  app:&VcsArtifactApp<A,M>,control:&mut NativeDecodeControl<'_>,
 )->Result<Self,Fault>{
  let generation=app.store.generation_now();
  let revision=app.store.content_revision_now();
  let child_generation=app.child_content_generation;
  let parent=app.store.snapshot_read().map_err(semio_framework_diagnostic::FaultFrom::into_fault)?;
  let snapshot_owner=app.store.snapshot_owner();
  if !std::ptr::eq(snapshot_owner.as_ref(),parent.get()){return Err(frame_fault(ValueError::new(ValueRefusalKind::InvariantViolated,"parent Store snapshot alias differs from its real leased owner")))}
  let children=ChildContentView::clone(&app.child_content_root);
  let projection=A::child_restore_projection(parent.get())?;
  let envelope=app.store.envelope();
  let dialect=envelope.dialect.as_ref().ok_or_else(||frame_fault(ValueError::new(ValueRefusalKind::InvalidValue,"parent frame has no declared envelope dialect")))?;
  let count=children.root.as_ref().map_or(0,|root|root.len);
  control.scoped_stage(|control|{
   let total=count.checked_add(1).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"child frame stage count overflow"))?;
   control.begin_stage(total)?;
   if let Some(root)=children.root.as_ref(){
    for entry in root.pages.iter().flatten().flat_map(|page|page.entries.iter().flatten()){
     control.step()?;
     let owner=entry.captured.owner();
     if owner.parent.artifact_id!=envelope.id||&owner.parent.dialect!=dialect{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"child frame root belongs to a different declared parent"))}
    }
   }
   control.step()?;
   control.checkpoint()
  }).map_err(frame_fault)?;
  let incoming=children.root.iter().flat_map(|root|root.pages.iter().flatten()).flat_map(|page|page.entries.iter().flatten()).map(|entry|{
   let captured=&entry.captured;
   let target=captured.reference();
   (captured.owner().slot.as_str(),semio_framework_schema_composition::ChildRefFields{
    child_id:captured.owner().child_id.as_str(),artifact_id:target.artifact_id.as_str(),
    artifact_kind:target.dialect.artifact_kind.as_str(),standard:target.dialect.standard.as_str(),subset:target.dialect.subset.as_str(),
   })
  });
  projection.admit_complete(incoming).map_err(projection_fault)?;
  control.checkpoint().map_err(frame_fault)?;
  if !parent.commit_authority_matches(generation,revision)||app.store.generation_now()!=generation||app.store.content_revision_now()!=revision||app.child_content_generation!=child_generation{
   return Err(frame_fault(ValueError::new(ValueRefusalKind::InvariantViolated,"parent or child root publication changed during synchronous frame capture")))
  }
  Ok(Self{parent:Some(parent),snapshot_owner:Some(snapshot_owner),children:Some(children),generation,revision,child_generation})
 }
 pub(crate) fn snapshot(&self)->Result<&A::Snapshot,ValueError>{
  self.parent.as_ref().map(store::SnapshotRead::get).ok_or_else(||ValueError::new(ValueRefusalKind::InvariantViolated,"parent frame read was already transferred to retirement"))
 }
 pub(crate) fn snapshot_owner(&self)->Result<std::sync::Arc<A::Snapshot>,ValueError>{
  let read=self.parent.as_ref().ok_or_else(||ValueError::new(ValueRefusalKind::InvariantViolated,"parent frame lease was already transferred"))?;
  let owner=self.snapshot_owner.as_ref().ok_or_else(||ValueError::new(ValueRefusalKind::InvariantViolated,"parent frame snapshot alias was already transferred"))?;
  if !std::ptr::eq(owner.as_ref(),read.get()){return Err(ValueError::new(ValueRefusalKind::InvariantViolated,"parent frame alias differs from its authentic read"))}
  Ok(std::sync::Arc::clone(owner))
 }
 pub(crate) fn children(&self)->Result<&ChildContentView,ValueError>{
  self.children.as_ref().ok_or_else(||ValueError::new(ValueRefusalKind::InvariantViolated,"child frame root was already transferred to retirement"))
 }
 pub(crate) fn generation(&self)->u64{self.generation}
 pub(crate) fn revision(&self)->[u8;32]{self.revision}
 pub(crate) fn child_generation(&self)->u64{self.child_generation}
 pub(crate) fn capture_child<S:Send+Sync+'static,F>(&self,slot:&str,select:F)->Result<store::ArtifactChildRead<S>,ValueError>
 where F:for<'a> FnOnce(&'a A::Snapshot)->Result<&'a store::ArtifactChild<S>,ValueError>{
  let handle=select(self.snapshot()?)?;
  let read=self.children()?.capture_read::<S>(slot,&handle.child_id,&handle.target.dialect)?;
  read.check_identity(slot,&handle.child_id,&handle.target)?;
  Ok(read)
 }
}
